package com.smartmanager.nativeapp;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.View;import android.widget.*;import java.util.*;
/** Native multi-router profile list. Selection updates the active shared connection only. */
public final class RouterProfilesActivity extends Activity {private LinearLayout page;private ListView list;private RouterProfilesStore store;private List<RouterProfilesStore.Profile> profiles=new ArrayList<>();private final int NAVY=Color.rgb(22,47,80),BLUE=Color.rgb(23,103,177);@Override public void onCreate(Bundle b){super.onCreate(b);store=new RouterProfilesStore(this);build();load();}private void build(){page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(16,20,16,30);page.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);page.setBackgroundColor(Color.rgb(237,244,250));ScrollView s=new ScrollView(this);s.addView(page);setContentView(s);page.addView(txt("ملفات الراوترات",24));Button add=button("إضافة ملف اتصال",BLUE);add.setOnClickListener(v->dialog(null));page.addView(add);list=new ListView(this);page.addView(list,new LinearLayout.LayoutParams(-1,650));}private void load(){try{profiles=store.all();ArrayList<String> labels=new ArrayList<>();for(RouterProfilesStore.Profile p:profiles)labels.add(p.name+"\n"+p.host+":"+p.port+(p.tls?" TLS":""));if(labels.isEmpty())labels.add("لا توجد ملفات محفوظة");list.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,labels));list.setOnItemClickListener((a,v,pos,id)->{if(pos<profiles.size())dialog(profiles.get(pos));});}catch(Exception e){Toast.makeText(this,"تعذر قراءة الأرشيف المشفر",Toast.LENGTH_LONG).show();}}private void dialog(RouterProfilesStore.Profile old){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);EditText n=f("اسم الملف",old==null?"":old.name,p),h=f("IP أو DNS",old==null?"":old.host,p),po=f("المنفذ",old==null?"8728":old.port,p),u=f("المستخدم",old==null?"":old.user,p),pw=f("كلمة المرور",old==null?"":old.password,p);pw.setInputType(0x81);CheckBox tls=new CheckBox(this);tls.setText("TLS");tls.setChecked(old!=null&&old.tls);p.addView(tls);AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle(old==null?"إضافة راوتر":"تعديل ملف الراوتر").setView(p).setNegativeButton("إلغاء",null).setPositiveButton("حفظ",(d,w)->{try{String id=old==null?UUID.randomUUID().toString():old.id;store.upsert(new RouterProfilesStore.Profile(id,n.getText().toString().trim(),h.getText().toString().trim(),po.getText().toString().trim(),u.getText().toString().trim(),pw.getText().toString(),tls.isChecked()));activate(id);load();}catch(Exception e){Toast.makeText(this,"فشل الحفظ دون حذف السجل",Toast.LENGTH_LONG).show();}});if(old!=null)b.setNeutralButton("حذف",(d,w)->new AlertDialog.Builder(this).setTitle("تأكيد الحذف").setMessage("سيُحذف ملف الاتصال فقط ولن تُحذف دفعاته").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(x,y)->{try{store.remove(old.id);load();}catch(Exception e){Toast.makeText(this,"فشل الحذف",Toast.LENGTH_LONG).show();}}));b.show();}private void activate(String id)throws Exception{for(RouterProfilesStore.Profile p:store.all())if(p.id.equals(id)){getSharedPreferences("router_connection",MODE_PRIVATE).edit().putString("router_name",p.name).putString("host",p.host).putString("port",p.port).putString("user",p.user).putBoolean("tls",p.tls).apply();new SecureConnectionStore(this).put(p.password);return;}}private EditText f(String h,String v,LinearLayout p){EditText e=new EditText(this);e.setHint(h);e.setText(v);e.setSingleLine(true);p.addView(e);return e;}private Button button(String s,int c){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(c));return b;}private TextView txt(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(NAVY);t.setPadding(8,10,8,10);return t;}}
